<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\ValueObject\TenantLoginProviderDisabledVO;
use Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\ValueObject\Holder\TenantLoginProviderDisabledAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantLoginProviderDisabledAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TenantLoginProviderDisabledAttributeHolderUnitTest extends TestCase
{
        /**
         * Asserts that the code attribute is not assigned by default
         * and that isDisabled returns null on a freshly created holder.
         */
        public function testDisabledNotAssignedByDefault(): void
        {
            // Arrange
            $holder = new ImplWithTenantLoginProviderDisabledAttributeHolderUnitTest();

            // Assert
            $this->assertFalse($holder->isDisabledAssigned());
            $this->assertNull($holder->isDisabled());
        }
}
class ImplWithTenantLoginProviderDisabledAttributeHolderUnitTest
{
  use TenantLoginProviderDisabledAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedDisabledRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultDisabled();
    }}
